_TRUE_VALUES = {"1", "true", "yes", "on"}
_FALSE_VALUES = {"0", "false", "no", "off", ""}


def _coerce_bool(value: str) -> bool:
    lowered = value.strip().lower()
    if lowered in _TRUE_VALUES:
        return True
    if lowered in _FALSE_VALUES:
        return False
    raise ValueError(f"cannot coerce {value!r} to bool")


def _coerce(value, default):
    """Coerce `value` to the type of `default` (bool, int, float, str)."""
    if isinstance(default, bool):
        return _coerce_bool(value)
    if isinstance(default, int):
        return int(value)
    if isinstance(default, float):
        return float(value)
    return str(value)


def load_config(defaults: dict, env: dict) -> dict:
    """Return a copy of `defaults` where any env var APP_<KEY> overrides the
    value for key <key> (lowercased), coerced to the type of the default."""
    cfg = dict(defaults)
    for env_key, env_value in env.items():
        if not env_key.startswith("APP_"):
            continue
        key = env_key[len("APP_"):].lower()
        if key not in cfg:
            continue
        cfg[key] = _coerce(env_value, cfg[key])
    return cfg
